from collections import Counter


class UnionFind:
  def __init__(self, n):
    self.par = [x for x in range(n)]

  def find(self, x):
    if x == self.par[x]:
      return x
    self.par[x] = self.find(self.par[x])
    return self.par[x]

  def unite(self, x, y):
    x = self.find(x)
    y = self.find(y)
    if x != y:
      self.par[y] = x


