def initialize_maze(h, w):
    grid = [["."] * (w + 2) for _ in range(h + 2)]

    for row in range(h + 2):
        grid[row][0] = "#"
        grid[row][w + 1] = "#"

    for col in range(w + 2):
        grid[0][col] = "#"
        grid[h + 1][col] = "#"

    return grid


