def prime_decomposition(n):
    i = 2
    table = []
    while i * i <= n:
        while n % i == 0:
            n //= i
            table.append(i)
        i += 1
    if n > 1:
        table.append(n)
    return table

def main():
    n = ni()
    prime_count = Counter(prime_decomposition(n))
    ans = 0
    for p in prime_count.values():
        i = 1
        while p - i >= 0:
            p -= i
            ans += 1
            i += 1
    print(ans)


