def simplify(s):
    res = []
    o = 0
    e = 0
    for c in s:
        if c == ")" and res and res[-1] == "(":
            res.pop()
            o -= 1
        else:
            res.append(c)
            if c == "(":
                o += 1
            else:
                e += 1
    return res, o, e


