# エラトステネスの篩
def prime_eratosthenes(n):
    prime_list = []
    num_set = set()
    for i in range(2, n + 1):
        if i not in num_set:
            prime_list.append(i)
            for j in range(i * i, n + 1, i):
                num_set.add(j)
    return prime_list


