def prime_factor(n):
    factors = [0] * (n+1)
    for i in range(2, int(n**0.5)+1):
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count != 0:
            factors[i] = count
    if n != 1:
        factors[n] = 1
    return factors

