def prime_factorize(n):
    prime_factors = {}
    i = 2
    while i ** 2 <= n:
        exp = 0
        while n % i == 0:
            exp += 1
            n //= i
        if exp:
            prime_factors[i] = exp
        i += 1

    if n != 1:
        prime_factors[n] = 1
    return prime_factors

