def Reverse(str, A, B):
    a = int(A)
    b = int(B)
    if a == 0:
        str = str[0:a] + str[b::-1] + str[b + 1:]
    else:
        str = str[0:a] + str[b:a - 1:-1] + str[b + 1:]
    return str

def Replace(str, a, b, c):
    str2 = ''
    Str = list(str)
    for i in range(int(b) - int(a) + 1):
        Str[i + int(a)] = c[i]
    for i in range(len(Str)):
        str2 += Str[i]
    return str2

