def solve(N: int, M: int, x: "List[int]", y: "List[int]", z: "List[int]"):
    ret = -float('inf')
    for b in range(8):
        c = [1] * 3
        for k in range(3):
            if (1 << k) & b:
                c[k] = -1
        s = []
        for i in range(N):
            s.append(x[i] * c[0] + y[i] * c[1] + z[i] * c[2])
        s.sort(reverse=True)
        ret = max(ret, sum(s[:M]))
    print(ret)
    return

