    ih, iw = 0, 0

    while ih < h:
        yield (ih, iw)

        if ih % 2 == 0:
            if iw == w - 1:
                ih += 1
            else:
                iw += 1
        else:
            if iw == 0:
                ih += 1
            else:
                iw -= 1


