def count_paths(passed, cur, d, n):
#     print(f'{passed=}, {cur=}')
    if len(passed) == n-1:
        return 1
    ans = 0
    for nx in d[cur]:
        if nx not in passed:
            ans += count_paths(passed+[cur], nx, d, n)
    return ans

