pos = {}

def bfs(cur, pre, p):
    stack = deque([(cur, pre, p)])
    while stack:
        cur, pre, p = stack.popleft()
        if cur in pos:
            if p != pos[cur]:
                print('No')
                sys.exit()
        else:
            pos[cur] = p

            for e, d in E[cur]:
                if e != pre:
                    stack.append([e, cur, p + d])

