def solve(N, M):
    ans = []
    now = 0
    for d in range(M, 0, -2):
        ans.append((now, now + d))
        now += 1

    now = M + 1
    for d in range(M - 1, 0, -2):
        ans.append((now, (now + d) % N))
        now += 1

    return ans


