def solve(y, x, field, used):

    num_white, num_black = 0, 0
    que = deque()
    que.append((y, x))
    used[y][x] = True

    while len(que) != 0:
        now = que.pop()

        if field[now[0]][now[1]] == '.':
            num_white += 1
        else:
            num_black += 1

        for i in range(4):
            ny = now[0] + dy4[i]
            nx = now[1] + dx4[i]

            if inside(ny, nx, len(field), len(field[0])):
                if field[ny][nx] != field[now[0]][now[1]]:
                    if not used[ny][nx]:
                        que.append((ny, nx))
                        used[ny][nx] = True

    return num_white * num_black


