def gcd(x, y):
  b = max(x, y)
  s = min(x, y)
  r = b % s
  while r != 0:
    b = s
    s = r
    r = b % s
  return s

def lcm(x, y):
  return (x * y) // gcd(x,y)

def nasu(a, b):
  g = gcd(a, b)
  if g < 0:
    g *= -1
  if b < 0:
    a *= -1
    b *= -1
  return [a // g, b // g]

