class Unionfind:
    def __init__(self,n):
        self.par=[x for x in range(n)]
        self.rank=[1]*n
        self.num=[1]*n

    def root(self,a):
        if self.par[a]==a : return a
        parent=self.root(self.par[a])
        self.par[a]=parent
        return parent

    def unite(self,a,b):
        ra,rb=self.root(a),self.root(b)
        out=self.num[ra]*self.num[rb]
        if self.rank[ra]<self.rank[rb]:
            ra,rb=rb,ra
        self.par[rb]=ra
        self.num[ra]+=self.num[rb]
        if self.rank[ra]==self.rank[rb]:
            self.rank[ra]+=1
        return out

    def same(self,a,b):
        return self.root(a)==self.root(b)

    def com_num(self,a,b):
        if self.same(a,b): return 0
        else : return self.unite(a,b)


