from collections import deque
from sys import stdin

def create_links(n, k):
  links = [[] for _ in range(n)]
  for i in range(k):
    p, q = map(int, stdin.readline().split())
    links[p - 1].append(q - 1)
    links[q - 1].append(p - 1)
  return links

def create_groups(n, links):
  groups = list(range(n))
  for i in range(n):
    if groups[i] != i:
      continue
    d = deque()
    d.append(i)
    while len(d) != 0:
      j = d.popleft()
      for k in links[j]:
        if groups[k] != i:
          groups[k] = i
          d.append(k)
  return groups

