    is_prime = [False] * 2 + [True] * (n - 1)
    for i in [2] + list(range(3, int(n ** 0.5) + 1, 2)):
        if not is_prime[i]: continue
        for j in range(2 * i, n + 1 ,i):
            is_prime[j] = False
    return is_prime

