    t = [[0] * (N + 1) for _ in range(N + 1)]
    for Li, Ri in zip(L, R):
        Li -= 1
        Ri -= 1
        t[Li + 1][Ri + 1] += 1
    for i in range(N):
        for j in range(N + 1):
            t[i + 1][j] += t[i][j]
    for i in range(N + 1):
