import sys


def solve(N: int, S: str):
    h = [set()]
    for c in S:
        h.append(h[-1] | set(c))
    t = [set()]
    for c in reversed(S):
        t.append(t[-1] | set(c))
    return max(len(hh & tt) for hh, tt in zip(h, reversed(t)))

