def print_func(s, order):
    print(s[order[1]:order[2]+1])


def reverse_func(s, order):
    ans = list(s[order[1]:order[2]+1])
    ans.reverse()
    s = s[:order[1]]+''.join(ans)+s[order[2]+1:]
    return s


def replace_func(s, order):
    cnt = 0
    s = list(s)
    for i in range(order[1], order[2]+1):
        s[i] = str(order[3])[cnt]
        cnt += 1
    s = ''.join(s)
    return s


