    AB = deque()
    for i in range(M):
        AB.append(map(int,input().split()))
    diff_pairs = [0]*M
    AB.reverse()
    prev = 0
    for i,(a,b) in enumerate(AB):
        if not uf.same(a,b):
            num_a = uf.size(a)
            num_b = uf.size(b)
            prev += num_a * num_b
            uf.union(a,b)
        diff_pairs[M-i-1] = prev
    outputs = deque()
    sum_d = 0
    prev = diff_pairs[0]
    for i in range(1,M):
        sum_d += prev-diff_pairs[i]
        outputs.append(sum_d)
        prev = diff_pairs[i]
    outputs.append(sum_d+1)
    print('\n'.join(map(str,outputs)))



