class UnionFind():
    def __init__(self, n):
        self.parents = [-1]*n

    def root(self, x):
        if self.parents[x] < 0:
            return x
        else:
            return self.root(self.parents[x])

    def unite(self, x, y):
        x = self.root(x)
        y = self.root(y)
        if x == y:
            return
        else:
            if x > y:
                x, y = y, x
            self.parents[x] += self.parents[y]
            self.parents[y] = x
            return

