def factorize(x):
    res = {}
    p = 2
    while p * p <= x:
        if x % p != 0: 
            p += 1
            continue
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        res[p] = cnt
        p += 1
    if x != 1:
        res[x] = 1
    return res

